28	    void enterImpl(QueryTreeNodePtr & node)
29	    {
30	        auto * function_node = node->as<FunctionNode>();
31	        if (!function_node || !function_node->isAggregateFunction())
32	            return;
33	
34	        if (!uniq_functions_names.contains(function_node->getFunctionName()))
35	            return;
36	
37	        for (auto & argument : function_node->getArguments().getNodes())
38	        {
39	            auto * argument_function_node = argument->as<FunctionNode>();
40	            if (!argument_function_node || !argument_function_node->isOrdinaryFunction())
41	                continue;
42	
43	            auto function = FunctionFactory::instance().tryGet(argument_function_node->getFunctionName(), context);
44	            if (!function || !function->isInjective({}))
45	                continue;
46	
47	            auto & inner_arguments = argument_function_node->getArguments().getNodes();
48	            if (inner_arguments.size() != 1)
49	                continue;
50	
51	            /// Replace `uniq(f(x))` with `uniq(x)` for injective `f`
